import {esc,icon,badge,btn,title,dateString} from './ui.js';
import {makeMissions,orderedLessons,DAY} from './core.js';
export function today({state,catalog,ui}){
 const missions=makeMissions(state,catalog,state.settings.sessionMinutes),mission=missions[0],completed=Object.values(state.completedLessons).filter(x=>!x.stale).length;
 const nextLesson=mission?.kind==='lesson'?catalog.lessons.find(l=>l.id===mission.lessonId):null;
 const module=catalog.modules.find(m=>m.id===nextLesson?.moduleId)||catalog.modules[0];
 const missionLink=mission?.kind==='review'?`#practice/${mission.exerciseId}?review=1&language=${mission.language}`:`#learn/${mission?.lessonId||catalog.lessons[0]?.id}`;
 const practiceCount=new Set(state.attempts.filter(a=>a.passed===true&&!a.stale).map(a=>a.exerciseId)).size;
 const activeDays=new Set(state.attempts.filter(a=>a.at>Date.now()-7*DAY).map(a=>new Date(a.at).toDateString())).size;
 const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);const n=state.attempts.filter(a=>a.at>=d.getTime()&&a.at<d.getTime()+DAY).length;return `<div class="day"><div class="day-bar"><span style="height:${Math.min(100,n*20)}%"></span></div>${new Intl.DateTimeFormat('id-ID',{weekday:'narrow'}).format(d)}</div>`;}).join('');
 const nearLessons=orderedLessons(state,catalog).filter(l=>!state.completedLessons[l.id]||state.completedLessons[l.id].stale).slice(0,3);
 const milestone=catalog.modules.filter(m=>['m04','m16'].includes(m.id)).filter(m=>m.lessonIds.every(id=>state.completedLessons[id]&&!state.completedLessons[id].stale)).at(-1);
 const roleDue=milestone&&(!state.settings.roleReviewedAt||state.settings.roleReviewedAt<Math.max(...milestone.lessonIds.map(id=>state.completedLessons[id].at)));
 return `${title('A little progress, every day',`Selamat belajar, ${(state.settings.name||'Reydian').split(' ')[0]}.`,'Satu konsep yang dipahami dengan baik adalah satu langkah maju.',`<span class="date-label">${dateString(Date.now())}</span>`)}${roleDue?`<div class="banner"><strong>${milestone.id==='m04'?'Fondasi selesai':'Core patterns selesai'}.</strong> Tinjau target role dan gap evidence sebelum melangkah lebih jauh. ${btn('Role-fit checkpoint','#career','secondary small')}</div>`:''}<div class="dashboard-grid"><section><div class="mission-hero"><div class="hero-top"><span class="eyebrow">Your next small step</span><div class="segmented" aria-label="Durasi sesi">${[15,45,90].map(n=>`<button type="button" data-action="session" data-value="${n}" class="${state.settings.sessionMinutes===n?'selected':''}" aria-pressed="${state.settings.sessionMinutes===n}">${n} min</button>`).join('')}</div></div><div class="mission-body">${badge(mission?.kind==='review'?'TIME TO RECALL':`MODULE ${module?.id.slice(1)||'01'} · ${module?.stage||'FOUNDATIONS'}`,'lime')}<h2>${esc(mission?.title||'Mulai perjalananmu.')}</h2><p>${mission?.kind==='review'?'Tarik kembali idenya dari ingatan. Review hari ini tidak harus menghabiskan seluruh sesi.':'Pahami konsepnya, lihat contoh, lalu coba sendiri. Kamu tidak perlu terburu-buru.'}</p><div class="mission-meta"><span>${icon('clock')} ${mission?.minutes||20} menit</span><span>${icon('book')} ${mission?.kind==='review'?'Active recall':'Baca · pahami · praktik'}</span></div>${btn(mission?.kind==='review'?'Mulai review':completed?'Lanjutkan belajar':'Mulai pelajaran pertama',missionLink)}</div><svg class="mission-art" viewBox="0 0 200 220" aria-hidden="true"><path d="M24 190V130H75V80H126V30H177" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M24 190H177" stroke="currentColor" opacity=".15"/><circle cx="24" cy="130" r="13" fill="#e8f3ad" stroke="currentColor"/><circle cx="75" cy="80" r="13" fill="#e8f3ad" stroke="currentColor"/><circle cx="126" cy="30" r="13" fill="#215c47"/><path d="m120 30 4 4 8-8" stroke="#fff" stroke-width="2" fill="none"/><rect x="129" y="128" width="47" height="47" rx="12" fill="#fff" opacity=".7"/><text x="152" y="158" text-anchor="middle" font-family="monospace" font-size="20" fill="#215c47">{ }</text></svg><div class="hero-footer"><span>${icon('shield')} Penguasaan dibangun dari bukti, bukan streak.</span><span>${completed} / ${catalog.lessons.length} pelajaran dipelajari</span></div></div><div class="stats-row"><div class="stat"><div class="stat-label">${icon('book')} Pelajaran</div><strong>${completed}<span class="muted" style="font-size:15px"> / ${catalog.lessons.length}</span></strong><small>Ditandai sudah dipelajari</small></div><div class="stat"><div class="stat-label">${icon('code')} Latihan benar</div><strong>${practiceCount}<span class="muted" style="font-size:15px"> / ${catalog.exercises.length}</span></strong><small>Unik, bukan jumlah percobaan</small></div><div class="stat"><div class="stat-label">${icon('review')} Review due</div><strong>${ui.dueCount}</strong><small>Boleh dijadwalkan ulang</small></div></div><div class="panel"><div class="panel-heading"><h2>Berikutnya di jalurmu</h2><a href="#roadmap">Lihat learning path ↗</a></div>${nearLessons.map((l,i)=>`<a class="lesson-row" href="#learn/${esc(l.id)}"><span class="row-number">${String(i+1).padStart(2,'0')}</span><div class="row-text"><h3>${esc(l.title)}</h3><p>${esc(catalog.modules.find(m=>m.id===l.moduleId)?.title)} · ${l.minutes} menit</p></div><span class="arrow">${icon('arrow')}</span></a>`).join('')||'<p class="muted">Semua pelajaran dipelajari. Review dan proyek adalah langkah berikutnya.</p>'}</div></section><aside class="dashboard-aside"><div class="panel"><div class="panel-heading"><h3>Ritme belajarmu</h3>${badge('7 hari','outline')}</div><p class="muted" style="font-size:12px">Sedikit dan konsisten, dengan ruang untuk istirahat.</p><div class="activity-week">${week}</div><div class="week-footer"><strong>${activeDays} hari aktif</strong> minggu ini.<br>Aktivitas ditampilkan dari percobaan nyata.</div><div class="path-progress"><span>Perjalanan belajar</span><strong>${Math.round(completed/catalog.lessons.length*100)||0}%</strong></div><div class="progress-track"><span style="width:${completed/catalog.lessons.length*100||0}%"></span></div></div><div class="quote-panel"><div class="eyebrow">A mindset to keep</div><p>“Bisakah aku menjelaskan mengapa solusi ini benar, dan kapan ia bisa gagal?”</p><small>Pertanyaan yang lebih berguna daripada sekadar “sudah selesai”.</small></div><div class="panel section-gap"><div class="panel-heading"><h3>Kenali arahmu</h3>${icon('briefcase')}</div><p class="muted" style="font-size:13px">Periksa target role sejak awal. DSA, proyek, testing, dan komunikasi perlu tumbuh bersama.</p><div class="section-gap">${btn('Buka career checkpoint','#career','secondary small')}</div></div></aside></div>`;
}
